package com.oldschoolnetwork.lite;
import android.app.Activity;import android.os.*;import android.content.Intent;import android.text.*;import android.text.style.*;import android.text.method.LinkMovementMethod;import android.view.View;import android.widget.*;import java.net.URL;
/** Text-first documentation reader; no WebView or website JavaScript is required. */
public final class DocumentsActivity extends Activity {
 private String address;private final Handler ui=new Handler();
 public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.lite_document);address=getIntent().getStringExtra("url");if(address==null)address="https://oldschoolnetwork.online/downloads/docs/categories/account/";findViewById(R.id.document_back).setOnClickListener(new View.OnClickListener(){public void onClick(View v){finish();}});findViewById(R.id.document_retry).setOnClickListener(new View.OnClickListener(){public void onClick(View v){load();}});load();}
 private void load(){((TextView)findViewById(R.id.document_text)).setText("Loading documentation…");Api.WORK.execute(new Runnable(){public void run(){try{
  URL url=new URL(address);if(!"https".equals(url.getProtocol())||!url.getHost().equals("oldschoolnetwork.online")||!url.getPath().startsWith("/downloads/docs/"))throw new Exception("Unknown documentation page.");
  String html=new String(HttpsTransport.request(DocumentsActivity.this,address,null,1024*1024),"UTF-8");html=html.replaceAll("(?is)<script\\b[^>]*>.*?</script>","").replaceAll("(?is)<style\\b[^>]*>.*?</style>","").replaceAll("(?is)<(?:header|footer|nav)\\b[^>]*>.*?</(?:header|footer|nav)>","");
  final SpannableString text=new SpannableString(Html.fromHtml(html));for(final URLSpan link:text.getSpans(0,text.length(),URLSpan.class)){if(link.getURL().startsWith("javascript:")||link.getURL().startsWith("mailto:")||link.getURL().startsWith("tel:")){text.removeSpan(link);continue;}final String destination=new URL(url,link.getURL()).toString();int start=text.getSpanStart(link),end=text.getSpanEnd(link);text.removeSpan(link);text.setSpan(new ClickableSpan(){public void onClick(View v){try{URL target=new URL(destination);if(target.getHost().equals("oldschoolnetwork.online")&&target.getPath().startsWith("/downloads/docs/"))startActivity(new Intent(DocumentsActivity.this,DocumentsActivity.class).putExtra("url",destination));else startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(destination)));}catch(Exception ignored){}}},start,end,Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);}
  ui.post(new Runnable(){public void run(){if(isFinishing())return;TextView body=(TextView)findViewById(R.id.document_text);body.setText(text);body.setMovementMethod(LinkMovementMethod.getInstance());}});
 }catch(final Exception error){ui.post(new Runnable(){public void run(){if(!isFinishing())((TextView)findViewById(R.id.document_text)).setText("Could not load documentation. "+error.getMessage());}});}}});}
}
